    PERFORM id FROM wego.tours_operator_tour
    WHERE slug IN ('banana-boat','bedouin-dinner-camel-ride','cairo-by-bus','cairo-by-plane','camel-horse-ride','dahab-colored-canyon','diving-course','dolphin-show','double-buggy-camel-ride','evening-cruise','glass-bottom-boat','luxor-by-plane','mount-sinai-st-catherine','parasailing-adventure','ras-mohamed-by-bus','ras-mohamed-white-island-boat','sharm-airport-transfer','sinai-dream-sailboat','speed-boat-adventure','st-catherine-dahab','submarine','sunset-quad-bike','super-safari-adventure','swimming-with-dolphins','tiran-island-boat-trip','tube-boat','turkish-bath')
