    PERFORM c.tour_id FROM wego.tours_operator_tour_content c
    JOIN wego.tours_operator_tour t ON t.id=c.tour_id
    WHERE t.slug IN ('banana-boat','bedouin-dinner-camel-ride','cairo-by-bus','cairo-by-plane','camel-horse-ride','dahab-colored-canyon','diving-course','dolphin-show','double-buggy-camel-ride','evening-cruise','glass-bottom-boat','luxor-by-plane','mount-sinai-st-catherine','parasailing-adventure','ras-mohamed-by-bus','ras-mohamed-white-island-boat','sharm-airport-transfer','sinai-dream-sailboat','speed-boat-adventure','st-catherine-dahab','submarine','sunset-quad-bike','super-safari-adventure','swimming-with-dolphins','tiran-island-boat-trip','tube-boat','turkish-bath')
    ORDER BY c.tour_id,c.locale,c.stage FOR UPDATE OF c;
    PERFORM f.tour_id FROM wego.tours_operator_tour_facts f
    JOIN wego.tours_operator_tour t ON t.id=f.tour_id
    WHERE t.slug IN ('banana-boat','bedouin-dinner-camel-ride','cairo-by-bus','cairo-by-plane','camel-horse-ride','dahab-colored-canyon','diving-course','dolphin-show','double-buggy-camel-ride','evening-cruise','glass-bottom-boat','luxor-by-plane','mount-sinai-st-catherine','parasailing-adventure','ras-mohamed-by-bus','ras-mohamed-white-island-boat','sharm-airport-transfer','sinai-dream-sailboat','speed-boat-adventure','st-catherine-dahab','submarine','sunset-quad-bike','super-safari-adventure','swimming-with-dolphins','tiran-island-boat-trip','tube-boat','turkish-bath')
    ORDER BY f.tour_id,f.stage FOR UPDATE OF f;
    PERFORM o.tour_id FROM wego.tours_operator_tour_price_option o
    JOIN wego.tours_operator_tour t ON t.id=o.tour_id
    WHERE t.slug='sharm-airport-transfer'
    ORDER BY o.tour_id,o.code FOR UPDATE OF o;

